// Shared probe library for black-box observation of /workspace/dataset/test3_executable
import { execFile, execFileSync } from 'node:child_process';
export const EXE = '/workspace/dataset/test3_executable';
export const CONC = 48;

/** Run once, synchronously. Returns {rc, out, err, lines} */
export function runSync(domain, strict = 'True') {
  try {
    const out = execFileSync(EXE, ['--domain', domain, '--strict', strict],
      { encoding: 'utf8', maxBuffer: 1 << 26 });
    return { rc: 0, out, err: '', lines: out.split('\n') };
  } catch (e) {
    return { rc: e.status ?? 1, out: e.stdout ?? '', err: e.stderr ?? '', lines: (e.stdout ?? '').split('\n') };
  }
}

/** Run many domains in parallel. items: string[] (domains). Returns array of {rc,out,err,lines}. */
export async function runMany(domains, strict = 'True', conc = CONC) {
  const res = new Array(domains.length);
  let next = 0;
  const worker = async () => {
    for (;;) {
      const i = next++;
      if (i >= domains.length) return;
      res[i] = await new Promise(r => execFile(EXE, ['--domain', domains[i], '--strict', strict],
        { encoding: 'utf8', maxBuffer: 1 << 26 },
        (e, so, se) => r({ rc: e ? (e.code ?? 1) : 0, out: so, err: se, lines: so.split('\n') })));
    }
  };
  await Promise.all(Array.from({ length: Math.min(conc, domains.length) }, worker));
  return res;
}

export const hex = cp => 'U+' + cp.toString(16).toUpperCase().padStart(4, '0');

/** Compact a sorted list of [lo,hi] or ints into range pairs */
export function toRanges(sortedInts) {
  const out = [];
  for (const v of sortedInts) {
    const last = out[out.length - 1];
    if (last && last[1] === v - 1) last[1] = v; else out.push([v, v]);
  }
  return out;
}
